import json,sys
sys.path.insert(0,'/root/build');import gltf_mesh as G
L=[('fox','/root/mm3/x/fox_minecraft',.7,0),('sniffer','/root/mm3/x/minecraft_sniffer',1.75,0),('frog','/root/mm3/x/minecraft_frog',.5,0),('wither','/root/mm3/x/minecraft_animated_wither_boss',3.5,0),('fan_arrow','/root/mm3/x/minecraft_arrow',-.5,0),('ghast','minecraft_-_ghast',4,0),('phantom','minecraft_-_phantom',.5,0),('slime','minecraft_-_slime',.52,0),('snow_golem','minecraft_-_snow_golem',1.9,0),('wolf','minecraft_-_wolf',.85,0),('tadpole','minecraft_tadpole',.3,0)]
YAW=json.load(open('/root/build/fan_yaw.json')) if __import__('os').path.exists('/root/build/fan_yaw.json') else {}
out={};keys=[]
outs=['/home/claude/bbsite/gui/','/home/claude/blockcraft/gui/','/home/claude/repo/gui/']
for n,d,h,y in L:
  ps,tx=G.convert(d if d.startswith('/') else '/root/mm2/x/'+d,'fan_'+n,h,YAW.get(n,y),outs);out[n]=ps;keys+=tx
import gltf_anim
try:
  gw=json.load(open('/root/mm3/x/minecraft_animated_wither_boss/scene.gltf'));names=[n.get('name') for n in gw['nodes']]
  ch=[gw['nodes'][c['target']['node']].get('name') for c in gw['animations'][0]['channels'] if c['target']['path']=='rotation']
  T,A=gltf_anim.sample('/root/mm3/x/minecraft_animated_wither_boss',{n:n for n in set(ch)},ai=0)
  WA={'dur':T,'f':A}
except Exception as e: print('wither anim',e); WA=None
HEAD = "// generated by tools/gen_fan.py: mob models from CC-BY Sketchfab models (see README credits), drawn with their own textures\n"
NEWDEF = "const FAN_NEW = { fox: { w: .6, h: .7, hp: 10, speed: 1.6, sound: 'mob/fox/ambient1', hurt: 'mob/fox/hurt1', death: 'mob/fox/death1', step: null, drop: [], shy: 1 }, fan_arrow: { w: .1, h: .1, hp: 1, hide: 1 } };\nfor (const k in FAN_NEW) if (!MOBDEF[k]) MOBDEF[k] = Object.assign({ tex: 'fan_' + k + '_0' }, FAN_NEW[k]);\n"
WAJ = ("if (MOBDEF.wither) MOBDEF.wither.anim = " + json.dumps(WA, separators=(',', ':')) + ";\n") if WA else ""
js = HEAD + "const FAN_MODELS = " + json.dumps(out, separators=(',', ':')) + ";\n" + NEWDEF + "for (const k in FAN_MODELS) if (MOBDEF[k]) { MOBDEF[k].parts = FAN_MODELS[k]; MOBDEF[k].fan = 1; delete MOBDEF[k].tw; }\n" + WAJ
for d in ['/home/claude/bbsite/js/','/home/claude/blockcraft/js/','/home/claude/repo/js/']: open(d+'fanmobs.js','w').write(js)
print(len(js)//1024,'KB',keys)
json.dump(keys,open('/root/build/fan_keys.json','w'))
